-- StudyFlow AI — initial schema (Cloudflare D1 / SQLite)
--
-- Conventions
--   * ids are UUID strings generated by the application.
--   * timestamps are integer milliseconds since the Unix epoch.
--   * every user-owned table carries user_id so authorization can be enforced
--     with a single predicate in the data-access layer (D1 has no RLS).
--   * JSON columns are validated with json_valid().

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE CHECK (length(email) BETWEEN 3 AND 320),
  password_hash TEXT NOT NULL,
  display_name TEXT CHECK (display_name IS NULL OR length(display_name) <= 120),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);

-- The session token itself is never stored: id is the SHA-256 of the token.
CREATE TABLE auth_sessions (
  id TEXT PRIMARY KEY CHECK (length(id) = 64),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at INTEGER NOT NULL,
  last_used_at INTEGER NOT NULL,
  user_agent TEXT,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX auth_sessions_user_idx ON auth_sessions(user_id);
CREATE INDEX auth_sessions_expiry_idx ON auth_sessions(expires_at);

-- Fixed-window counters used to throttle sign-in / sign-up attempts.
CREATE TABLE auth_attempts (
  key TEXT PRIMARY KEY,
  count INTEGER NOT NULL,
  window_start INTEGER NOT NULL
) WITHOUT ROWID;

CREATE TABLE profiles (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  notes_language TEXT NOT NULL DEFAULT 'auto'
    CHECK (notes_language IN ('auto', 'es', 'en', 'bilingual')),
  remove_fillers INTEGER NOT NULL DEFAULT 1 CHECK (remove_fillers IN (0, 1)),
  transcription_delay TEXT NOT NULL DEFAULT 'medium'
    CHECK (transcription_delay IN ('minimal', 'low', 'medium', 'high', 'xhigh')),
  audio_review_enabled INTEGER NOT NULL DEFAULT 0 CHECK (audio_review_enabled IN (0, 1)),
  audio_retention_days INTEGER
    CHECK (audio_retention_days IS NULL OR audio_retention_days BETWEEN 1 AND 3650),
  monthly_budget_usd REAL CHECK (monthly_budget_usd IS NULL OR monthly_budget_usd >= 0),
  job_budget_usd REAL CHECK (job_budget_usd IS NULL OR job_budget_usd >= 0),
  recording_notice_ack_at INTEGER,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);

-- ---------------------------------------------------------------------------
-- Subjects and lectures
-- ---------------------------------------------------------------------------

CREATE TABLE subjects (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
  color TEXT NOT NULL DEFAULT 'green'
    CHECK (color IN ('green', 'blue', 'amber', 'rose', 'violet', 'slate', 'teal', 'orange')),
  -- Transcription keyword hints (JSON array of strings).
  keywords TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(keywords) AND json_type(keywords) = 'array'),
  description TEXT CHECK (description IS NULL OR length(description) <= 2000),
  archived_at INTEGER,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE UNIQUE INDEX subjects_user_name_uq ON subjects(user_id, name COLLATE NOCASE);

-- Capture lifecycle (status) and AI processing (processing_status) are
-- separate so that a lecture can never be "recording" and "processing" at once.
CREATE TABLE lecture_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  subject_id TEXT REFERENCES subjects(id) ON DELETE SET NULL,
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 200),
  status TEXT NOT NULL DEFAULT 'created'
    CHECK (status IN ('created', 'recording', 'paused', 'recovering', 'finalizing', 'ready', 'failed')),
  processing_status TEXT NOT NULL DEFAULT 'idle'
    CHECK (processing_status IN ('idle', 'queued', 'processing', 'completed', 'failed')),
  started_at INTEGER,
  ended_at INTEGER,
  -- Active recording time (pauses excluded); the audio timeline length.
  duration_ms INTEGER NOT NULL DEFAULT 0 CHECK (duration_ms >= 0),
  last_heartbeat_at INTEGER,
  audio_mime TEXT,
  transcription_mode TEXT CHECK (transcription_mode IS NULL OR transcription_mode IN ('realtime', 'turns')),
  keywords TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(keywords) AND json_type(keywords) = 'array'),
  -- Languages identified in the transcript, e.g. ["en","es"].
  languages TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(languages) AND json_type(languages) = 'array'),
  failure_reason TEXT,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  -- AI processing only exists for lectures whose capture is complete.
  CHECK (processing_status = 'idle' OR status = 'ready')
);
CREATE INDEX lecture_sessions_user_idx ON lecture_sessions(user_id, created_at DESC);
CREATE INDEX lecture_sessions_subject_idx ON lecture_sessions(subject_id, created_at DESC);
CREATE INDEX lecture_sessions_status_idx ON lecture_sessions(user_id, status);

-- Allowed capture-status transitions (mirrors src/lib/sessions/state-machine.ts).
CREATE TABLE session_status_transitions (
  from_status TEXT NOT NULL,
  to_status TEXT NOT NULL,
  PRIMARY KEY (from_status, to_status)
) WITHOUT ROWID;

INSERT INTO session_status_transitions (from_status, to_status) VALUES
  ('created', 'recording'),
  ('created', 'failed'),
  ('recording', 'paused'),
  ('recording', 'recovering'),
  ('recording', 'finalizing'),
  ('recording', 'failed'),
  ('paused', 'recording'),
  ('paused', 'recovering'),
  ('paused', 'finalizing'),
  ('paused', 'failed'),
  ('recovering', 'recording'),
  ('recovering', 'finalizing'),
  ('recovering', 'failed'),
  ('finalizing', 'ready'),
  ('finalizing', 'failed'),
  ('failed', 'recovering'),
  ('failed', 'finalizing');

CREATE TRIGGER lecture_sessions_status_guard
BEFORE UPDATE OF status ON lecture_sessions
WHEN OLD.status <> NEW.status
  AND NOT EXISTS (
    SELECT 1 FROM session_status_transitions t
    WHERE t.from_status = OLD.status AND t.to_status = NEW.status
  )
BEGIN
  SELECT RAISE(ABORT, 'invalid_status_transition');
END;

-- One row per audio file stored in R2. A row exists only after the server
-- received the bytes, verified their SHA-256 and wrote them to R2, so the
-- client may mark a chunk as synced only once this row is confirmed.
CREATE TABLE audio_chunks (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  seq INTEGER NOT NULL CHECK (seq >= 0),
  start_ms INTEGER NOT NULL CHECK (start_ms >= 0),
  end_ms INTEGER NOT NULL,
  duration_ms INTEGER NOT NULL CHECK (duration_ms >= 0),
  -- Audio at the start of this file that duplicates the end of the previous
  -- one (recorders overlap during rotation so no audio is lost).
  overlap_ms INTEGER NOT NULL DEFAULT 0 CHECK (overlap_ms >= 0),
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL CHECK (size_bytes > 0),
  sha256 TEXT NOT NULL CHECK (length(sha256) = 64),
  r2_key TEXT NOT NULL UNIQUE,
  -- 1 when recovered from an interrupted recorder (truncated file).
  partial INTEGER NOT NULL DEFAULT 0 CHECK (partial IN (0, 1)),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  CHECK (end_ms >= start_ms),
  UNIQUE (session_id, seq)
);
CREATE INDEX audio_chunks_user_idx ON audio_chunks(user_id, created_at);

CREATE TABLE transcript_segments (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  -- Client turn sequence number; unique per session, makes upserts idempotent.
  seq INTEGER NOT NULL CHECK (seq >= 0),
  provider_item_id TEXT,
  text TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'final' CHECK (status IN ('final', 'failed', 'gap')),
  source TEXT NOT NULL CHECK (source IN ('realtime', 'turns', 'recovery', 'review')),
  -- Segment-level, approximate positions on the audio timeline.
  start_ms INTEGER NOT NULL CHECK (start_ms >= 0),
  end_ms INTEGER NOT NULL,
  language TEXT NOT NULL DEFAULT 'und' CHECK (language IN ('es', 'en', 'mixed', 'und')),
  language_source TEXT NOT NULL DEFAULT 'heuristic' CHECK (language_source IN ('heuristic', 'model')),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  CHECK (end_ms >= start_ms),
  UNIQUE (session_id, seq)
);
-- Audio order, not arrival order.
CREATE INDEX transcript_segments_order_idx ON transcript_segments(session_id, start_ms, seq);

CREATE VIRTUAL TABLE transcript_segments_fts USING fts5(
  text,
  content = 'transcript_segments',
  content_rowid = 'rowid',
  tokenize = 'unicode61 remove_diacritics 2'
);
CREATE TRIGGER transcript_segments_fts_ai AFTER INSERT ON transcript_segments BEGIN
  INSERT INTO transcript_segments_fts(rowid, text) VALUES (new.rowid, new.text);
END;
CREATE TRIGGER transcript_segments_fts_ad AFTER DELETE ON transcript_segments BEGIN
  INSERT INTO transcript_segments_fts(transcript_segments_fts, rowid, text) VALUES ('delete', old.rowid, old.text);
END;
CREATE TRIGGER transcript_segments_fts_au AFTER UPDATE OF text ON transcript_segments BEGIN
  INSERT INTO transcript_segments_fts(transcript_segments_fts, rowid, text) VALUES ('delete', old.rowid, old.text);
  INSERT INTO transcript_segments_fts(rowid, text) VALUES (new.rowid, new.text);
END;

CREATE TABLE lecture_markers (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (type IN ('important', 'exam', 'confused', 'note')),
  at_ms INTEGER NOT NULL CHECK (at_ms >= 0),
  note TEXT CHECK (note IS NULL OR length(note) <= 2000),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX lecture_markers_session_idx ON lecture_markers(session_id, at_ms);

CREATE TABLE lecture_attachments (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  file_name TEXT NOT NULL CHECK (length(file_name) BETWEEN 1 AND 255),
  kind TEXT NOT NULL CHECK (kind IN ('pdf', 'docx', 'pptx')),
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL CHECK (size_bytes > 0),
  sha256 TEXT NOT NULL CHECK (length(sha256) = 64),
  r2_key TEXT NOT NULL UNIQUE,
  page_count INTEGER,
  extraction_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (extraction_status IN ('pending', 'processing', 'ready', 'needs_ocr', 'failed')),
  extraction_error TEXT,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX lecture_attachments_session_idx ON lecture_attachments(session_id);

-- ---------------------------------------------------------------------------
-- Study material
-- ---------------------------------------------------------------------------

CREATE TABLE study_documents (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  kind TEXT NOT NULL
    CHECK (kind IN ('notes', 'summary_quick', 'summary_full', 'summary_last_minute')),
  language TEXT NOT NULL CHECK (language IN ('es', 'en', 'bilingual')),
  title TEXT NOT NULL,
  current_version_id TEXT,
  -- Plain text of the current version, kept for full-text search.
  search_text TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  UNIQUE (session_id, kind)
);

CREATE VIRTUAL TABLE study_documents_fts USING fts5(
  title,
  search_text,
  content = 'study_documents',
  content_rowid = 'rowid',
  tokenize = 'unicode61 remove_diacritics 2'
);
CREATE TRIGGER study_documents_fts_ai AFTER INSERT ON study_documents BEGIN
  INSERT INTO study_documents_fts(rowid, title, search_text) VALUES (new.rowid, new.title, new.search_text);
END;
CREATE TRIGGER study_documents_fts_ad AFTER DELETE ON study_documents BEGIN
  INSERT INTO study_documents_fts(study_documents_fts, rowid, title, search_text)
    VALUES ('delete', old.rowid, old.title, old.search_text);
END;
CREATE TRIGGER study_documents_fts_au AFTER UPDATE OF title, search_text ON study_documents BEGIN
  INSERT INTO study_documents_fts(study_documents_fts, rowid, title, search_text)
    VALUES ('delete', old.rowid, old.title, old.search_text);
  INSERT INTO study_documents_fts(rowid, title, search_text) VALUES (new.rowid, new.title, new.search_text);
END;

-- Immutable snapshots. Every AI generation, manual save and restore creates
-- a new version, so manual edits are never lost silently.
CREATE TABLE study_document_versions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  document_id TEXT NOT NULL REFERENCES study_documents(id) ON DELETE CASCADE,
  version_number INTEGER NOT NULL CHECK (version_number >= 1),
  origin TEXT NOT NULL CHECK (origin IN ('ai', 'ai_section', 'user', 'restore')),
  content TEXT NOT NULL CHECK (json_valid(content)),
  word_count INTEGER NOT NULL DEFAULT 0,
  job_id TEXT,
  label TEXT,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  UNIQUE (document_id, version_number)
);

-- Retrieval units for chat and search: transcript windows, attachment pages
-- and note sections, with optional embeddings (Float32 little-endian BLOB).
CREATE TABLE document_sources (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  source_type TEXT NOT NULL CHECK (source_type IN ('transcript', 'attachment', 'notes')),
  attachment_id TEXT REFERENCES lecture_attachments(id) ON DELETE CASCADE,
  page_number INTEGER,
  seq_from INTEGER,
  seq_to INTEGER,
  start_ms INTEGER,
  end_ms INTEGER,
  section_key TEXT,
  text TEXT NOT NULL,
  embedding BLOB,
  embedding_model TEXT,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  CHECK (source_type <> 'attachment' OR (attachment_id IS NOT NULL AND page_number IS NOT NULL)),
  CHECK (source_type <> 'transcript' OR (seq_from IS NOT NULL AND seq_to IS NOT NULL))
);
CREATE INDEX document_sources_session_idx ON document_sources(session_id, source_type);
CREATE INDEX document_sources_attachment_idx ON document_sources(attachment_id, page_number);

CREATE VIRTUAL TABLE document_sources_fts USING fts5(
  text,
  content = 'document_sources',
  content_rowid = 'rowid',
  tokenize = 'unicode61 remove_diacritics 2'
);
CREATE TRIGGER document_sources_fts_ai AFTER INSERT ON document_sources BEGIN
  INSERT INTO document_sources_fts(rowid, text) VALUES (new.rowid, new.text);
END;
CREATE TRIGGER document_sources_fts_ad AFTER DELETE ON document_sources BEGIN
  INSERT INTO document_sources_fts(document_sources_fts, rowid, text) VALUES ('delete', old.rowid, old.text);
END;
CREATE TRIGGER document_sources_fts_au AFTER UPDATE OF text ON document_sources BEGIN
  INSERT INTO document_sources_fts(document_sources_fts, rowid, text) VALUES ('delete', old.rowid, old.text);
  INSERT INTO document_sources_fts(rowid, text) VALUES (new.rowid, new.text);
END;

CREATE TABLE exam_questions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  subject_id TEXT REFERENCES subjects(id) ON DELETE SET NULL,
  qtype TEXT NOT NULL CHECK (qtype IN ('mcq', 'short', 'essay', 'oral', 'case')),
  level INTEGER CHECK (level IS NULL OR level BETWEEN 1 AND 4),
  concept TEXT NOT NULL,
  concept_key TEXT NOT NULL,
  prompt TEXT NOT NULL,
  options TEXT CHECK (options IS NULL OR (json_valid(options) AND json_type(options) = 'array')),
  correct_option INTEGER,
  answer TEXT NOT NULL,
  explanation TEXT,
  rubric TEXT CHECK (rubric IS NULL OR json_valid(rubric)),
  source_refs TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(source_refs)),
  -- 1 when the question needs material beyond what was explained in class.
  extends_syllabus INTEGER NOT NULL DEFAULT 0 CHECK (extends_syllabus IN (0, 1)),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  CHECK (qtype <> 'mcq' OR (options IS NOT NULL AND correct_option IS NOT NULL))
);
CREATE INDEX exam_questions_session_idx ON exam_questions(session_id, qtype);
CREATE INDEX exam_questions_subject_idx ON exam_questions(user_id, subject_id);

CREATE TABLE exam_attempts (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  question_id TEXT NOT NULL REFERENCES exam_questions(id) ON DELETE CASCADE,
  session_id TEXT REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  subject_id TEXT REFERENCES subjects(id) ON DELETE SET NULL,
  answer TEXT,
  selected_option INTEGER,
  score REAL NOT NULL CHECK (score BETWEEN 0 AND 1),
  verdict TEXT NOT NULL CHECK (verdict IN ('correct', 'partial', 'incorrect')),
  feedback TEXT,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX exam_attempts_question_idx ON exam_attempts(question_id, created_at);
CREATE INDEX exam_attempts_subject_idx ON exam_attempts(user_id, subject_id, created_at);

CREATE TABLE flashcards (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  subject_id TEXT REFERENCES subjects(id) ON DELETE SET NULL,
  card_type TEXT NOT NULL
    CHECK (card_type IN ('definition', 'qa', 'article', 'term', 'comparison', 'exception')),
  front TEXT NOT NULL CHECK (length(front) BETWEEN 1 AND 2000),
  back TEXT NOT NULL CHECK (length(back) BETWEEN 1 AND 6000),
  concept_key TEXT NOT NULL,
  source_refs TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(source_refs)),
  ease REAL NOT NULL DEFAULT 2.5 CHECK (ease >= 1.3),
  interval_days REAL NOT NULL DEFAULT 0 CHECK (interval_days >= 0),
  repetitions INTEGER NOT NULL DEFAULT 0,
  lapses INTEGER NOT NULL DEFAULT 0,
  due_at INTEGER NOT NULL,
  last_reviewed_at INTEGER,
  suspended INTEGER NOT NULL DEFAULT 0 CHECK (suspended IN (0, 1)),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
-- One card per concept per subject: regeneration never duplicates concepts.
CREATE UNIQUE INDEX flashcards_concept_uq ON flashcards(user_id, ifnull(subject_id, ''), concept_key);
CREATE INDEX flashcards_due_idx ON flashcards(user_id, suspended, due_at);
CREATE INDEX flashcards_session_idx ON flashcards(session_id);

CREATE TABLE flashcard_reviews (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  flashcard_id TEXT NOT NULL REFERENCES flashcards(id) ON DELETE CASCADE,
  grade TEXT NOT NULL CHECK (grade IN ('again', 'hard', 'good', 'easy')),
  prev_interval_days REAL NOT NULL,
  next_interval_days REAL NOT NULL,
  prev_ease REAL NOT NULL,
  next_ease REAL NOT NULL,
  reviewed_at INTEGER NOT NULL
);
CREATE INDEX flashcard_reviews_card_idx ON flashcard_reviews(flashcard_id, reviewed_at);

CREATE TABLE chat_conversations (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  title TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX chat_conversations_session_idx ON chat_conversations(session_id, updated_at);

CREATE TABLE chat_messages (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  conversation_id TEXT NOT NULL REFERENCES chat_conversations(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  content TEXT NOT NULL,
  -- Structured assistant answer: grounded part, additional explanation, citations.
  payload TEXT CHECK (payload IS NULL OR json_valid(payload)),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX chat_messages_conversation_idx ON chat_messages(conversation_id, created_at);

-- ---------------------------------------------------------------------------
-- Processing jobs and cost accounting
-- ---------------------------------------------------------------------------

CREATE TABLE processing_jobs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT REFERENCES lecture_sessions(id) ON DELETE CASCADE,
  job_type TEXT NOT NULL CHECK (job_type IN (
    'notes', 'summaries', 'exam', 'flashcards', 'attachment', 'index', 'section', 'recovery_transcription'
  )),
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'running', 'completed', 'failed', 'cancelled')),
  -- Real pipeline stage, shown to the user (no fake percentages).
  stage TEXT,
  -- Prevents two concurrent jobs doing the same work (see partial index).
  dedupe_key TEXT NOT NULL,
  params TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(params)),
  result TEXT CHECK (result IS NULL OR json_valid(result)),
  error TEXT,
  estimated_cost_usd REAL,
  cost_usd REAL NOT NULL DEFAULT 0,
  runner TEXT CHECK (runner IS NULL OR runner IN ('workflow', 'local')),
  workflow_instance_id TEXT,
  attempt INTEGER NOT NULL DEFAULT 1,
  started_at INTEGER,
  finished_at INTEGER,
  heartbeat_at INTEGER,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  updated_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE UNIQUE INDEX processing_jobs_active_uq ON processing_jobs(user_id, dedupe_key)
  WHERE status IN ('queued', 'running');
CREATE INDEX processing_jobs_session_idx ON processing_jobs(session_id, created_at);
CREATE INDEX processing_jobs_status_idx ON processing_jobs(status, heartbeat_at);

-- Persisted intermediate results: a retried job resumes after the last
-- completed step instead of starting over.
CREATE TABLE job_steps (
  job_id TEXT NOT NULL REFERENCES processing_jobs(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  output TEXT NOT NULL CHECK (json_valid(output)),
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER)),
  PRIMARY KEY (job_id, name)
) WITHOUT ROWID;

CREATE TABLE usage_events (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT REFERENCES lecture_sessions(id) ON DELETE SET NULL,
  job_id TEXT REFERENCES processing_jobs(id) ON DELETE SET NULL,
  kind TEXT NOT NULL CHECK (kind IN ('live_transcription', 'file_transcription', 'llm', 'embedding')),
  model TEXT NOT NULL,
  input_tokens INTEGER NOT NULL DEFAULT 0,
  cached_input_tokens INTEGER NOT NULL DEFAULT 0,
  output_tokens INTEGER NOT NULL DEFAULT 0,
  audio_seconds REAL NOT NULL DEFAULT 0,
  cost_usd REAL NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL DEFAULT (CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER))
);
CREATE INDEX usage_events_user_idx ON usage_events(user_id, created_at);
CREATE INDEX usage_events_session_idx ON usage_events(session_id);
